import{mean,median,pct,sorted,stdev,fmt}from'./stats.js';import{RULES,confidence}from'./config.js';
export function attendanceMetrics(rows){const data=sorted(rows),values=data.map(r=>r.attendance);return{sampleSize:data.length,average:mean(values),median:median(values),total:values.reduce((a,b)=>a+b,0),highest:[...data].sort((a,b)=>b.attendance-a.attendance).slice(0,3),lowest:[...data].sort((a,b)=>a.attendance-b.attendance).slice(0,3),rollingAverage:data.map((r,i)=>({date:r.date,id:r.id,value:mean(values.slice(Math.max(0,i-4),i+1)),n:Math.min(i+1,5)})),confidence:confidence(data.length),warnings:!data.length?['No usable meetings.']:[]}}
export function compareRecent(rows,{period='meetings',window=3}={}){if(!Number.isInteger(window)||window<1||window>100)throw Error('Comparison window must be 1–100.');if(!['meetings','month'].includes(period))throw Error('Unsupported comparison period.');const data=sorted(rows);let recent,previous,label;if(period==='month'){const end=data.length?Date.parse(data.at(-1).date):0,cutoff=end-30*86400000;recent=data.filter(r=>Date.parse(r.date)>cutoff);previous=data.filter(r=>Date.parse(r.date)<=cutoff);label='last 30 days of recorded history vs earlier meetings'}else{recent=data.slice(-window);previous=data.slice(-window*2,-window);label=`last ${window} meetings vs previous ${window}`}
const sufficient=period==='month'?recent.length>=3&&previous.length>=3:recent.length===window&&previous.length===window;const current=mean(recent.map(r=>r.attendance)),baseline=mean(previous.map(r=>r.attendance));return{available:sufficient,label,sampleSize:recent.length+previous.length,recentCount:recent.length,previousCount:previous.length,current,baseline,change:sufficient?current-baseline:null,percentChange:sufficient?pct(current,baseline):null,recentIds:recent.map(r=>r.id),previousIds:previous.map(r=>r.id),confidence:confidence(data.length),warnings:sufficient?baseline===0?['Previous attendance was zero; percent change is undefined.']:[]:['Not enough meetings in both comparison periods.']}}
export function attendanceTrend(rows,options={}){const c=compareRecent(rows,options);return{...c,direction:!c.available?'Not enough history':c.percentChange==null?c.change===0?'Stable':c.change>0?'Improving':'Needs attention':c.percentChange>=RULES.healthChange?'Improving':c.percentChange<=-RULES.healthChange?'Needs attention':'Stable',definition:`At least ${RULES.healthChange}% change between comparison periods; otherwise stable.`}}
export function attendanceAnomalies(rows){if(rows.length<RULES.comparisons)return{available:false,sampleSize:rows.length,items:[],warnings:['At least five meetings are needed to flag unusual turnout.']};const values=rows.map(r=>r.attendance),center=median(values),mad=median(values.map(v=>Math.abs(v-center)));const threshold=mad?RULES.anomalyZ*1.4826*mad:Math.max(5,center*.5);return{available:true,sampleSize:rows.length,median:center,threshold,items:rows.filter(r=>Math.abs(r.attendance-center)>threshold).map(r=>({id:r.id,name:r.name,date:r.date,attendance:r.attendance,difference:r.attendance-center,direction:r.attendance>center?'Above typical':'Below typical'})),warnings:['Unusual turnout is a review flag, not proof of an error. No meetings are removed.'],method:mad?'Median absolute deviation, scaled by 1.4826; threshold 3.5.':'Zero median deviation: threshold is the larger of 5 attendees or 50% of median.'}}
export function compareCategories(rows,key,retentionData=null){if(!['type','promotion','time','weekday'].includes(key))throw Error('Unsupported comparison field.');const value=r=>key==='weekday'?['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][new Date(r.date+'T12:00:00Z').getUTCDay()]:r[key];const usable=rows.filter(r=>value(r)!=null),avg=mean(rows.map(r=>r.attendance));const groups=[...new Set(usable.map(value))].map(name=>{const subset=usable.filter(r=>value(r)===name),returning=retentionData?.perMeeting?.filter(p=>subset.some(r=>r.id===p.id));return{name,count:subset.length,average:mean(subset.map(r=>r.attendance)),median:median(subset.map(r=>r.attendance)),difference:mean(subset.map(r=>r.attendance))-avg,eligible:rows.length>=RULES.comparisons&&subset.length>=RULES.group,returningShare:returning?.length?returning.reduce((s,r)=>s+r.returning,0)/(returning.reduce((s,r)=>s+r.attendance,0)||1):null,confidence:confidence(subset.length)}}).sort((a,b)=>b.average-a.average);return{field:key,available:usable.length>0,sampleSize:usable.length,baseline:avg,groups,excludedRows:rows.filter(r=>value(r)==null).map(r=>({id:r.id,reason:`Missing ${key}.`})),warnings:groups.length<2?['At least two categories are needed for a comparison.']:['Category differences are associations; topics, timing, and promotion can overlap.'],best:groups.filter(g=>g.eligible).length>=2?groups.find(g=>g.eligible):null}}
